// v0.18.21-json-full-text-search
// Grid rendering, search, row operations, and detail navigation
// Generated by responsibility split. No functional change intended.

function loadRows() {
  const gd = gridDef();
  currentRows = getByPath(sourceData, gd.dataPath);
  if (!Array.isArray(currentRows)) throw new Error('mainGrid dataPath が Array ではありません: ' + gd.dataPath);
  filteredRows = currentRows.map((row, index) => ({row, index}));
  applySortToFilteredRows();
}

function gridRendererMode(gd=gridDef()) {
  const raw =
    gd?.grid?.renderer ?? gd?.grid?.displayStyle ?? gd?.grid?.display_style ?? gd?.grid?.style ??
    gd?.renderer ?? gd?.displayStyle ?? gd?.display_style ?? gd?.style ??
    'table';
  const mode = String(raw ?? '').trim().toLowerCase();
  if (['card', 'cards', 'document', 'doc', 'document-card', 'document_grid', 'document-grid', 'card_grid', 'card-grid'].includes(mode)) return 'document';
  return 'table';
}

function wantsDocumentGrid(gd=gridDef()) {
  return gridRendererMode(gd) === 'document';
}

function ensureGridHostElement(tagName) {
  const expected = String(tagName ?? 'table').toUpperCase();
  let host = $('dataGrid');
  if (!host) return null;
  if (host.tagName === expected) return host;
  const replacement = document.createElement(tagName);
  replacement.id = 'dataGrid';
  host.replaceWith(replacement);
  return replacement;
}

function setGridWrapMode(mode) {
  const wrap = document.querySelector('.table-wrap');
  if (!wrap) return;
  wrap.classList.toggle('document-grid-wrap', mode === 'document');
  wrap.classList.toggle('table-grid-wrap', mode !== 'document');
}

function renderGridFrame(gd) {
  $('gridCaption').textContent = gd.caption ?? 'Grid';
  $('gridCount').textContent = `${selectedDisplayPosition()} / ${currentRows.length}行目　表示 ${filteredRows.length} / 全 ${currentRows.length}件`;
  $('gridSection').classList.remove('hidden');
}

function renderGrid() {
  const gd = gridDef();
  if (wantsDocumentGrid(gd)) return renderByKey('gridDocument', gd);
  return renderByKey('gridTable', gd);
}

function tableGridVisibleFields(gd) {
  if (typeof GridColumnBuilder !== 'undefined' && GridColumnBuilder?.build) {
    return GridColumnBuilder.build(gd);
  }
  return (gd?.fields ?? []).filter(f => f.grid?.visible !== false);
}

function renderGridAggregateRow(thead, visibleFields) {
  if (typeof GridAggregator === 'undefined' || !GridAggregator?.build) return;
  const aggregateResult = GridAggregator.build({
    fields: visibleFields,
    currentRows,
    filteredRows,
    getValue: getByPath
  });
  if (!aggregateResult.has_aggregates) return;

  const row = document.createElement('tr');
  row.className = 'grid-aggregate-row';
  visibleFields.forEach(field => {
    const cell = document.createElement('th');
    cell.className = 'grid-aggregate-placeholder';
    const aggregate = aggregateResult.byField[field.field];
    if (aggregate) {
      cell.className = 'grid-aggregate-cell';
      cell.dataset.aggregateField = field.field;
      cell.dataset.aggregateOperator = aggregate.operator;
      cell.dataset.aggregateScope = aggregate.scope;
      if (field.type) cell.classList.add(field.type);

      const label = document.createElement('span');
      label.className = 'grid-aggregate-label';
      label.textContent = 'Σ';
      label.setAttribute('aria-hidden', 'true');
      const value = document.createElement('span');
      value.className = 'grid-aggregate-value';
      value.textContent = formatValue(aggregate.value, field);
      cell.append(label, value);
      const scopeDescription = aggregate.scope === 'all'
        ? `全${aggregate.source_count}件の合計`
        : `表示中${aggregate.source_count}件の合計`;
      const ignoredDescription = aggregate.ignored_count > 0
        ? ` / 数値対象外 ${aggregate.ignored_count}件`
        : '';
      cell.title = `${scopeDescription}: ${value.textContent}${ignoredDescription}`;
      cell.setAttribute('aria-label', `${aggregate.label} ${scopeDescription} ${value.textContent}`);
    } else {
      cell.setAttribute('aria-hidden', 'true');
    }
    row.appendChild(cell);
  });
  thead.appendChild(row);
}

function renderCompactGrid(gd=gridDef()) {
  renderGridFrame(gd);
  setGridWrapMode('table');
  const table = ensureGridHostElement('table');
  table.className = '';
  table.innerHTML = '';
  const visibleFields = tableGridVisibleFields(gd);
  const thead = document.createElement('thead');
  const trh = document.createElement('tr');
  trh.className = 'grid-column-header-row';
  visibleFields.forEach(f => {
    const th = document.createElement('th');
    th.classList.add('sortable');
    th.title = 'クリックでソート';
    const label = document.createElement('span');
    label.textContent = f.caption ?? f.field;
    th.appendChild(label);
    const mark = document.createElement('span');
    mark.className = 'sort-mark';
    mark.textContent = sortState.field === f.field ? (sortState.direction === 'asc' ? '▲' : '▼') : '';
    th.appendChild(mark);
    th.addEventListener('click', () => cycleSort(f.field));
    if (f.grid?.width) th.style.width = f.grid.width + 'px';
    trh.appendChild(th);
  });
  thead.appendChild(trh);
  renderGridAggregateRow(thead, visibleFields);
  table.appendChild(thead);
  const tbody = document.createElement('tbody');
  filteredRows.forEach(({row, index}) => {
    const tr = document.createElement('tr');
    applyGridRowEmphasis(tr, row);
    if (index === selectedIndex) tr.classList.add('selected');
    tr.addEventListener('click', () => { selectedIndex = index; renderGrid(); });
    tr.addEventListener('dblclick', () => openDetail(index));
    tr.addEventListener('contextmenu', (e) => {
      e.preventDefault();
      selectedIndex = index;
      renderGrid();
      showRowContextMenu(e.clientX, e.clientY, index);
    });
    visibleFields.forEach(f => {
      const td = document.createElement('td');
      if (f.type) td.classList.add(f.type);
      const value = getByPath(row, f.field);
      td.textContent = formatValue(value, f);
      if (f.grid?.display === 'json' || f.grid?.inlineJson === true || f.grid?.inline_json === true) {
        td.classList.add('grid-cell-inline-json');
        td.title = td.textContent;
      }
      applyGridCellEmphasis(td, f, row, value);
      if (f.grid?.width) td.style.maxWidth = f.grid.width + 'px';
      tr.appendChild(td);
    });
    tbody.appendChild(tr);
  });
  table.appendChild(tbody);
}

function documentGridConfig(gd) {
  return {
    ...(gd?.document ?? {}),
    ...(gd?.card ?? {}),
    ...(gd?.grid?.document ?? {}),
    ...(gd?.grid?.card ?? {})
  };
}

function fieldByName(gd, fieldName) {
  return (gd?.fields ?? []).find(f => f.field === fieldName) ?? null;
}

function normalizeDocumentFieldSpec(gd, raw) {
  if (typeof raw === 'string') {
    const field = fieldByName(gd, raw);
    return field ? { field, options: {} } : null;
  }
  if (!raw || typeof raw !== 'object') return null;
  const name = raw.field ?? raw.name ?? raw.key;
  if (!name) return null;
  const base = fieldByName(gd, name) ?? { field: String(name), type: raw.type ?? 'text', caption: raw.caption ?? raw.label ?? String(name) };
  return { field: { ...base, ...raw, field: base.field }, options: raw };
}

function documentGridFieldSpecs(gd, cfg=documentGridConfig(gd)) {
  const explicit = cfg.fields ?? cfg.itemFields ?? cfg.item_fields ?? gd?.grid?.documentFields ?? gd?.grid?.document_fields ?? gd?.grid?.cardFields ?? gd?.grid?.card_fields;
  if (Array.isArray(explicit) && explicit.length) {
    return explicit.map(item => normalizeDocumentFieldSpec(gd, item)).filter(Boolean);
  }
  return (gd?.fields ?? [])
    .filter(f => f.grid?.visible !== false)
    .filter(f => f.type !== 'chat' && f.type !== 'objectArray' && f.type !== 'stringArray')
    .map(field => ({ field, options: field.document ?? field.card ?? {} }));
}

function documentGridMetaFieldNames(gd, cfg=documentGridConfig(gd)) {
  const raw = cfg.metaFields ?? cfg.meta_fields ?? cfg.badgeFields ?? cfg.badge_fields ?? [];
  return normalizeArray(raw).map(x => typeof x === 'string' ? x : (x?.field ?? x?.name)).filter(Boolean);
}

function documentGridTitleFieldName(gd, cfg=documentGridConfig(gd)) {
  return cfg.titleField ?? cfg.title_field ?? gd?.keyField ?? 'title';
}

function documentGridEmptyHtml() {
  const span = document.createElement('span');
  span.className = 'document-grid-empty-value';
  span.textContent = '(空)';
  return span;
}

function documentGridMarkdownConfig(field, options={}) {
  if (typeof normalizeChatMarkdownConfig === 'function') {
    return normalizeChatMarkdownConfig(
      { enabled: false, allowLinks: true, allowImages: false },
      field?.markdown,
      field?.edit?.markdown,
      field?.display?.markdown,
      field?.document?.markdown,
      field?.card?.markdown,
      options?.markdown
    );
  }
  return field?.markdown ?? options?.markdown ?? { enabled: false };
}

function renderDocumentGridValue(value, field, options={}) {
  const box = document.createElement('div');
  box.className = 'document-grid-value-body';
  if (value == null || value === '') {
    box.appendChild(documentGridEmptyHtml());
    return box;
  }
  if (Array.isArray(value)) {
    box.textContent = `${value.length}件`;
    return box;
  }
  if (typeof value === 'object') {
    const pre = document.createElement('pre');
    pre.textContent = JSON.stringify(value, null, 2);
    box.appendChild(pre);
    return box;
  }
  const text = String(value);
  const mdCfg = documentGridMarkdownConfig(field, options);
  const displayAsMarkdown = Boolean(mdCfg?.enabled && (field?.type === 'textarea' || options?.markdown || field?.markdown));
  if (displayAsMarkdown && typeof renderMarkdownContent === 'function') {
    box.classList.add('markdown-rendered');
    box.innerHTML = renderMarkdownContent(text, mdCfg);
  } else {
    box.textContent = formatValue(value, field);
  }
  return box;
}

function isDocumentGridReadonly(field, options={}) {
  if (launchRuntime?.readonly) return true;
  return Boolean(options.readonly ?? field?.document?.readonly ?? field?.card?.readonly ?? field?.readonly ?? field?.edit?.readonly);
}

function createDocumentGridEditor(field, value) {
  let input;
  const control = field?.control ?? field?.edit?.control;
  if (field.type === 'select' || control === 'select' || Array.isArray(field.options)) {
    input = document.createElement('select');
    const blank = document.createElement('option');
    blank.value = '';
    blank.textContent = '';
    input.appendChild(blank);
    (field.options ?? []).forEach(opt => {
      const o = document.createElement('option');
      o.value = optionValue(opt, field);
      o.textContent = optionLabel(opt, field);
      input.appendChild(o);
    });
    setSelectValuePreservingUnknown(input, field, value);
  } else if (field.type === 'boolean') {
    input = document.createElement('select');
    ['', 'true', 'false'].forEach(v => {
      const o = document.createElement('option');
      o.value = v;
      o.textContent = v;
      input.appendChild(o);
    });
    input.value = value === true ? 'true' : value === false ? 'false' : '';
  } else if (field.type === 'number') {
    input = document.createElement('input');
    input.type = 'number';
    input.value = value ?? '';
  } else if (field.type === 'textarea' || control === 'textarea' || String(value ?? '').length > 80 || String(value ?? '').includes('\n')) {
    input = document.createElement('textarea');
    input.value = value == null ? '' : String(value);
    input.rows = Math.min(14, Math.max(3, String(value ?? '').split('\n').length + 1));
  } else {
    input = document.createElement('input');
    input.type = 'text';
    input.value = value ?? '';
  }
  input.className = 'document-grid-editor';
  input.dataset.field = field.field;
  input.dataset.type = field.type ?? 'text';
  return input;
}

function readDocumentGridEditorValue(field, input) {
  const raw = input?.value ?? '';
  return convertValue(field?.type, raw);
}

function enterDocumentGridFieldEditMode({ card, row, index, field, options, valueCell }) {
  if (!card || !row || !field || !valueCell) return;
  if (isDocumentGridReadonly(field, options)) return;
  if (valueCell.dataset.editing === 'true') return;
  selectedIndex = index;
  document.querySelectorAll('.document-grid-card.is-editing').forEach(el => el.classList.remove('is-editing'));
  card.classList.add('selected', 'is-editing');
  valueCell.dataset.editing = 'true';

  const originalValue = getByPath(row, field.field);
  const editor = createDocumentGridEditor(field, originalValue);
  valueCell.innerHTML = '';
  valueCell.appendChild(editor);

  let done = false;
  const commit = (message='カード編集を反映しました') => {
    if (done) return;
    done = true;
    const nextValue = readDocumentGridEditorValue(field, editor);
    setByPath(row, field.field, nextValue);
    applySearch();
    renderGrid();
    setStatus(`${message}: ${field.caption ?? field.field}`);
  };
  const cancel = () => {
    if (done) return;
    done = true;
    renderGrid();
    setStatus('カード編集をキャンセルしました');
  };

  editor.addEventListener('blur', () => commit(), { once: true });
  editor.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') {
      e.preventDefault();
      cancel();
      return;
    }
    if (e.key === 'F12' || ((e.ctrlKey || e.metaKey) && e.key === 'Enter') || (e.key === 'Enter' && editor.tagName !== 'TEXTAREA')) {
      e.preventDefault();
      commit('カード編集を反映しました');
    }
  });
  if (editor.tagName === 'SELECT') editor.addEventListener('change', () => commit(), { once: true });

  requestAnimationFrame(() => {
    editor.focus();
    if (editor.select && editor.tagName !== 'SELECT') editor.select();
  });
}

function createDocumentGridField({ card, row, index, field, options }) {
  const item = document.createElement('div');
  item.className = 'document-grid-field';
  const label = document.createElement('div');
  label.className = 'document-grid-label';
  label.textContent = options.label ?? options.caption ?? field.caption ?? field.field;
  const valueCell = document.createElement('div');
  valueCell.className = 'document-grid-value';
  valueCell.appendChild(renderDocumentGridValue(getByPath(row, field.field), field, options));

  if (!isDocumentGridReadonly(field, options)) {
    valueCell.tabIndex = 0;
    valueCell.title = 'クリックすると編集できます';
    valueCell.classList.add('is-editable');
    valueCell.addEventListener('click', (e) => {
      if (e.target.closest?.('a') && (e.ctrlKey || e.metaKey)) return;
      e.preventDefault();
      enterDocumentGridFieldEditMode({ card, row, index, field, options, valueCell });
    });
    valueCell.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        enterDocumentGridFieldEditMode({ card, row, index, field, options, valueCell });
      }
    });
  } else {
    valueCell.classList.add('readonly');
  }

  item.appendChild(label);
  item.appendChild(valueCell);
  return item;
}

function makeDocumentGridButton(label, title, onClick, className='ghost-button small') {
  const btn = document.createElement('button');
  btn.type = 'button';
  btn.className = `document-grid-action ${className}`;
  btn.textContent = label;
  btn.title = title;
  btn.addEventListener('click', (e) => {
    e.preventDefault();
    e.stopPropagation();
    onClick();
  });
  return btn;
}

function refreshAfterDocumentGridRowMutation(message) {
  applySearch();
  renderGrid();
  setStatus(message);
}

function insertDocumentGridRow(index=null, position='end', sourceRow=null) {
  if (!Array.isArray(currentRows)) return;
  applyHeaderEdits();
  const row = sourceRow ? createRowFromSourceRow(sourceRow) : createDefaultRow();
  let insertAt = currentRows.length;
  if (Number.isInteger(index) && index >= 0) insertAt = position === 'before' ? index : index + 1;
  insertAt = Math.max(0, Math.min(currentRows.length, insertAt));
  currentRows.splice(insertAt, 0, row);
  selectedIndex = insertAt;
  refreshAfterDocumentGridRowMutation(`カード行を追加しました: ${insertAt + 1}行目`);
}

function addDocumentGridRowAtEnd() {
  insertDocumentGridRow(null, 'end');
}

async function deleteDocumentGridRow(index) {
  if (!Array.isArray(currentRows) || index < 0 || !currentRows[index]) return;
  const ok = await showStudioConfirmDialog({
    title: 'このカード行を削除しますか？',
    message: 'この操作は画面上のデータから対象行を削除します。',
    detail: `index: ${index}`,
    okText: '削除する',
    cancelText: 'キャンセル',
    danger: true
  });
  if (!ok) return;
  currentRows.splice(index, 1);
  selectedIndex = -1;
  refreshAfterDocumentGridRowMutation('カード行を削除しました');
}

function duplicateDocumentGridRow(index) {
  if (!Array.isArray(currentRows) || index < 0 || !currentRows[index]) return;
  insertDocumentGridRow(index, 'after', currentRows[index]);
}

function moveDocumentGridRow(index, delta) {
  if (!Array.isArray(currentRows) || index < 0) return;
  const next = index + delta;
  if (next < 0 || next >= currentRows.length) return;
  const [row] = currentRows.splice(index, 1);
  currentRows.splice(next, 0, row);
  selectedIndex = next;
  refreshAfterDocumentGridRowMutation('カード行を移動しました');
}

function createDocumentGridCard(row, index, gd, cfg, fieldSpecs) {
  const card = document.createElement('section');
  card.className = 'document-grid-card';
  applyGridRowEmphasis(card, row);
  if (index === selectedIndex) card.classList.add('selected');
  card.addEventListener('click', () => {
    if (selectedIndex !== index) {
      selectedIndex = index;
      renderGrid();
    }
  });
  card.addEventListener('dblclick', (e) => {
    if (e.target.closest?.('button, input, select, textarea, a')) return;
    openDetail(index);
  });

  const header = document.createElement('div');
  header.className = 'document-grid-card-header';
  const titleWrap = document.createElement('div');
  titleWrap.className = 'document-grid-card-title-wrap';
  const kicker = document.createElement('div');
  kicker.className = 'document-grid-card-kicker';
  kicker.textContent = `${filteredRows.findIndex(x => x.index === index) + 1} / ${filteredRows.length}`;
  const h3 = document.createElement('h3');
  const titleField = fieldByName(gd, documentGridTitleFieldName(gd, cfg));
  h3.textContent = titleField ? (formatValue(getByPath(row, titleField.field), titleField) || '(no title)') : `行 ${index + 1}`;
  titleWrap.appendChild(kicker);
  titleWrap.appendChild(h3);

  const meta = document.createElement('div');
  meta.className = 'document-grid-card-meta';
  documentGridMetaFieldNames(gd, cfg).forEach(name => {
    const f = fieldByName(gd, name);
    if (!f) return;
    const chip = document.createElement('span');
    chip.className = 'document-grid-chip';
    chip.textContent = `${f.caption ?? f.field}: ${formatValue(getByPath(row, f.field), f)}`;
    meta.appendChild(chip);
  });
  titleWrap.appendChild(meta);
  header.appendChild(titleWrap);

  const actions = document.createElement('div');
  actions.className = 'document-grid-card-actions';
  actions.appendChild(makeDocumentGridButton('詳細', '従来の詳細ダイアログを開く', () => openDetail(index)));
  if (!launchRuntime?.readonly) {
    actions.appendChild(makeDocumentGridButton('＋上', 'このカードの上に空行を追加', () => insertDocumentGridRow(index, 'before')));
    actions.appendChild(makeDocumentGridButton('＋下', 'このカードの下に空行を追加', () => insertDocumentGridRow(index, 'after')));
    actions.appendChild(makeDocumentGridButton('複製', 'このカードを複製して下に追加', () => duplicateDocumentGridRow(index)));
    actions.appendChild(makeDocumentGridButton('↑', 'このカードを上へ移動', () => moveDocumentGridRow(index, -1)));
    actions.appendChild(makeDocumentGridButton('↓', 'このカードを下へ移動', () => moveDocumentGridRow(index, 1)));
    actions.appendChild(makeDocumentGridButton('削除', 'このカードを削除', () => deleteDocumentGridRow(index), 'ghost-button small danger'));
  }
  header.appendChild(actions);
  card.appendChild(header);

  const body = document.createElement('div');
  body.className = 'document-grid-card-body';
  fieldSpecs.forEach(({ field, options }) => {
    if (!field?.field) return;
    body.appendChild(createDocumentGridField({ card, row, index, field, options }));
  });
  card.appendChild(body);
  return card;
}

function renderDocumentGrid(gd=gridDef()) {
  renderGridFrame(gd);
  setGridWrapMode('document');
  const host = ensureGridHostElement('div');
  host.className = 'document-grid-host';
  host.innerHTML = '';
  const cfg = documentGridConfig(gd);
  const fieldSpecs = documentGridFieldSpecs(gd, cfg);

  const toolbar = document.createElement('div');
  toolbar.className = 'document-grid-toolbar';
  const note = document.createElement('div');
  note.className = 'document-grid-note';
  note.textContent = 'Card(Document) Grid: 値をクリックするとその場で編集できます。F12 / Ctrl+Enter / blur で反映、保存値はJSON原文です。';
  toolbar.appendChild(note);
  if (!launchRuntime?.readonly) {
    toolbar.appendChild(makeDocumentGridButton('＋末尾に追加', '末尾に空カードを追加', addDocumentGridRowAtEnd, 'primary-button small'));
  }
  host.appendChild(toolbar);

  if (!filteredRows.length) {
    const empty = document.createElement('div');
    empty.className = 'document-grid-empty-card';
    empty.textContent = '表示対象の行がありません。検索条件を見直すか、新規行を追加してください。';
    host.appendChild(empty);
    return;
  }

  filteredRows.forEach(({ row, index }) => {
    host.appendChild(createDocumentGridCard(row, index, gd, cfg, fieldSpecs));
  });
}



function fallbackMatchesStudioFullText(row, rawQuery) {
  const query = String(rawQuery ?? '').trim().toLowerCase();
  if (!query) return true;

  const values = [];
  const seen = new Set();
  const collect = (value) => {
    if (typeof value === 'string') {
      values.push(value);
      return;
    }
    if (value == null || typeof value !== 'object' || seen.has(value)) return;
    seen.add(value);
    if (Array.isArray(value)) value.forEach(collect);
    else Object.values(value).forEach(collect);
  };
  collect(row);
  return values.join('\n').toLowerCase().includes(query);
}

function applySearch() {
  const gd = gridDef();
  const inputs = [...$('searchForm').querySelectorAll('input, select, textarea')];
  const fullText = $('studioFullTextSearchInput')?.value ?? '';

  if (typeof SearchFilter !== 'undefined' && SearchFilter?.apply) {
    const criteria = SearchFilter.criteriaFromInputs(inputs, gd.fields ?? []);
    filteredRows = SearchFilter.apply(currentRows, criteria, { fullText });
  } else {
    // fallback: v0.18.7責務Interface読込前でも旧挙動を維持する。
    filteredRows = currentRows.map((row, index) => ({row, index})).filter(({row}) => {
      return inputs.every(inp => {
        const raw = inp.multiple
          ? [...inp.selectedOptions].map(opt => opt.value).filter(Boolean)
          : inp.value;
        if (Array.isArray(raw) && raw.length === 0) return true;
        if (raw === '') return true;
        const field = gd.fields.find(f => f.field === inp.dataset.field);
        if (!field) return true;
        const val = getByPath(row, field.field);
        const op = field.search?.operator ?? field.search?.match ?? (field.type === 'number' ? 'gte' : 'contains');
        if (Array.isArray(raw)) {
          const values = Array.isArray(val) ? val.map(v => String(v)) : [String(val ?? '')];
          return raw.some(x => values.includes(String(x)));
        }
        if (field.type === 'number') {
          const n = Number(raw);
          if (op === 'gte') return Number(val) >= n;
          if (op === 'lte') return Number(val) <= n;
          return Number(val) === n;
        }
        if (field.type === 'boolean') return String(val) === raw;
        if (op === 'equals') return String(val ?? '') === raw;
        return String(val ?? '').toLowerCase().includes(raw.toLowerCase());
      });
    });
    filteredRows = filteredRows.filter(({ row }) => fallbackMatchesStudioFullText(row, fullText));
  }

  // Overlay/Plugin SearchFilter は既存互換契約として温存する。
  // Copilotくんの studio_overlays がSearch stateへ重ねている場合も、ここで従来どおり後段適用される。
  if (typeof applyStudioPluginSearchFilters === 'function') {
    filteredRows = applyStudioPluginSearchFilters(filteredRows, { gd, inputs });
  }

  applySortToFilteredRows();
  renderGrid();
}


// v0.18.4-grid-csv-export:
// 現在Gridに表示されている行・列を、表示順のままUTF-8 BOM付きCSVで出力する。
function gridCsvKeyFieldName(gd) {
  const explicit = gd?.keyField ?? gd?.key_field ?? gd?.grid?.keyField ?? gd?.grid?.key_field;
  if (explicit) return String(explicit);
  const fields = gd?.fields ?? [];
  const candidates = ['message_id', 'id', 'key', 'code', 'name'];
  return candidates.find(name => fields.some(f => f.field === name)) ?? '';
}

function gridCsvBaseVisibleFields(gd) {
  if (!gd) return [];
  if (wantsDocumentGrid(gd) && typeof documentGridFieldSpecs === 'function') {
    return documentGridFieldSpecs(gd).map(spec => spec.field).filter(Boolean);
  }
  return tableGridVisibleFields(gd);
}

function gridCsvExportFields(gd) {
  const base = gridCsvBaseVisibleFields(gd);
  const keyFieldName = gridCsvKeyFieldName(gd);
  const fallbackField = { field: '_source_index', caption: '_source_index', type: 'number', virtual: true };
  if (typeof CsvExporter !== 'undefined' && CsvExporter?.resolveFields) {
    return CsvExporter.resolveFields({
      baseFields: base,
      allFields: gd?.fields ?? [],
      keyFieldName,
      fallbackField
    });
  }

  const out = [];
  const seen = new Set();
  const push = (field) => {
    if (!field?.field) return;
    const key = String(field.field);
    if (seen.has(key)) return;
    seen.add(key);
    out.push(field);
  };
  const keyAlreadyVisible = keyFieldName && base.some(f => f?.field === keyFieldName);
  if (keyFieldName && !keyAlreadyVisible) {
    push((gd?.fields ?? []).find(f => f.field === keyFieldName) ?? { field: keyFieldName, caption: keyFieldName, type: 'text' });
  }
  base.forEach(push);
  if (!out.length) out.push(fallbackField);
  return out;
}

function gridCsvHeaderForField(field) {
  return String(field?.field ?? field?.caption ?? '');
}

function gridCsvValue(row, sourceIndex, field) {
  if (field?.field === '_source_index') return String(sourceIndex);
  return formatValue(getByPath(row, field.field), field);
}

function csvEscapeCell(value) {
  const text = String(value ?? '');
  if (/[",\r\n]/.test(text)) return '"' + text.replace(/"/g, '""') + '"';
  return text;
}

function buildVisibleGridCsv() {
  const gd = gridDef();
  if (!gd || !Array.isArray(filteredRows)) throw new Error('Gridが読み込まれていません');
  const fields = gridCsvExportFields(gd);
  if (typeof CsvExporter !== 'undefined' && CsvExporter?.export) {
    return CsvExporter.export({
      rows: filteredRows,
      fields,
      valueForField: ({ row, index, field }) => gridCsvValue(row, index, field),
      includeBom: false
    });
  }
  const header = fields.map(field => csvEscapeCell(gridCsvHeaderForField(field))).join(',');
  const body = filteredRows.map(({ row, index }) => {
    return fields.map(field => csvEscapeCell(gridCsvValue(row, index, field))).join(',');
  });
  return [header, ...body].join('\r\n') + '\r\n';
}

function gridCsvTimestamp(date=new Date()) {
  return typeof studioFormatFileTimestamp === 'function'
    ? studioFormatFileTimestamp(date)
    : date.toLocaleString('sv-SE').replace(/[-: ]/g, '').slice(0, 15);
}

function gridCsvDataNameBase() {
  const candidates = [];
  try { if (typeof selectedDataName === 'function') candidates.push(selectedDataName()); } catch { /* ignore */ }
  candidates.push(currentLoadedDataDisplayPath, currentDataApiUrl, currentLoadedDataTitle, 'grid');
  const raw = candidates.map(x => String(x ?? '').trim()).find(Boolean) || 'grid';
  let name = raw.replace(/\\/g, '/').split(/[?#]/)[0].split('/').filter(Boolean).pop() || raw;
  name = name.replace(/\.json$/i, '');
  name = name.replace(/[<>:"/\\|?*\x00-\x1f]/g, '_').replace(/\s+/g, '_').replace(/_+/g, '_').replace(/^_+|_+$/g, '');
  return name || 'grid';
}

function exportVisibleGridCsv() {
  try {
    if (!sourceData || !viewDef) {
      setStatus('CSV出力するGridが読み込まれていません', { kind: 'warn', title: 'CSV出力' });
      return;
    }
    const csv = buildVisibleGridCsv();
    const fileName = `${gridCsvDataNameBase()}_${gridCsvTimestamp()}.csv`;
    const blob = new Blob(['\ufeff', csv], { type: 'text/csv;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = fileName;
    document.body.appendChild(a);
    a.click();
    a.remove();
    window.setTimeout(() => URL.revokeObjectURL(url), 1000);
    setStatus(`Grid CSVを出力しました: ${fileName} / ${filteredRows.length}件`, { kind: 'success', title: 'Grid CSV Export', toast: false });
  } catch (err) {
    console.error(err);
    setStatus('CSV出力エラー: ' + err.message, { kind: 'error', title: 'Grid CSV Export' });
  }
}


function cloneDefaultValue(value) {
  if (Array.isArray(value)) return value.map(cloneDefaultValue);
  if (value && typeof value === 'object') return typeof structuredClone === 'function' ? structuredClone(value) : JSON.parse(JSON.stringify(value));
  return value;
}

function defaultForField(field) {
  if ('defaultValue' in field) return cloneDefaultValue(field.defaultValue);
  if (field.type === 'number') return 0;
  if (field.type === 'boolean') return false;
  if (field.type === 'objectArray' || field.type === 'stringArray' || field.type === 'array') return [];
  if (field.type === 'select') return field.options?.length ? optionValue(field.options[0], field) : '';
  return '';
}

function createDefaultRow() {
  const gd = gridDef();
  const row = {};
  gd.fields.forEach(field => {
    if (field.create?.include === false) return;
    setByPath(row, field.field, defaultForField(field));
  });
  return assignNewRowKeys(row);
}
function addGridRow() {
  if (!Array.isArray(currentRows)) return;
  if (wantsDocumentGrid()) {
    addDocumentGridRowAtEnd();
    return;
  }
  applyHeaderEdits();
  const row = createDefaultRow();
  openNewDetail(row, '新規登録画面を開きました（反映するまで行は追加されません）');
}
async function deleteSelectedRow() {
  if (!Array.isArray(currentRows) || selectedIndex < 0) {
    setStatus('削除する行を選択してください');
    return;
  }
  const ok = await showStudioConfirmDialog({
    title: '選択中の1行を削除しますか？',
    message: 'この操作は画面上のデータから選択行を削除します。',
    detail: `index: ${selectedIndex}`,
    okText: '削除する',
    cancelText: 'キャンセル',
    danger: true
  });
  if (!ok) return;
  currentRows.splice(selectedIndex, 1);
  selectedIndex = -1;
  applySearch();
  setStatus('1行削除しました');
}


function copyRow(index) {
  if (!Array.isArray(currentRows) || index < 0) return;
  copiedRow = cloneData(currentRows[index]);
  setStatus(`行をコピーしました: ${index}`);
}

function nextNumberValue(fieldName) {
  const vals = (currentRows ?? [])
    .map(r => Number(getByPath(r, fieldName)))
    .filter(n => Number.isFinite(n));
  return vals.length ? Math.max(...vals) + 1 : 1;
}

function regexEscape(text) {
  return String(text).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function nextUniqueKeyValue(keyField, sourceValue) {
  const existing = new Set((currentRows ?? []).map(r => String(getByPath(r, keyField) ?? '')).filter(Boolean));
  const src = String(sourceValue ?? '').trim();
  const m = src.match(/^(.*?)(\d+)$/);
  if (m) {
    const prefix = m[1];
    const width = m[2].length;
    let maxNo = 0;
    const re = new RegExp('^' + regexEscape(prefix) + '(\\d+)$');
    existing.forEach(v => {
      const mm = v.match(re);
      if (mm) maxNo = Math.max(maxNo, Number(mm[1]));
    });
    let n = maxNo + 1;
    let candidate = prefix + String(n).padStart(width, '0');
    while (existing.has(candidate)) {
      n += 1;
      candidate = prefix + String(n).padStart(width, '0');
    }
    return candidate;
  }
  const base = src || 'row';
  let n = 1;
  let candidate = `${base}_copy_${n}`;
  while (existing.has(candidate)) {
    n += 1;
    candidate = `${base}_copy_${n}`;
  }
  return candidate;
}

function removeCreateExcludedFields(row) {
  const gd = gridDef();
  (gd.fields ?? []).forEach(field => {
    if (field.create?.include === false) {
      const parts = String(field.field ?? '').split('.');
      let cur = row;
      for (let i = 0; i < parts.length - 1; i++) {
        cur = cur?.[parts[i]];
        if (cur == null) return;
      }
      if (cur && Object.prototype.hasOwnProperty.call(cur, parts[parts.length - 1])) {
        delete cur[parts[parts.length - 1]];
      }
    }
  });
}

function assignNewRowKeys(row, sourceRow=null) {
  const gd = gridDef();
  const noField = (gd.fields ?? []).find(f => f.field === 'no' || String(f.field).toLowerCase() === 'no');
  if (noField) setByPath(row, noField.field, nextNumberValue(noField.field));
  if (gd.keyField) {
    const oldKey = sourceRow ? getByPath(sourceRow, gd.keyField) : getByPath(row, gd.keyField);
    setByPath(row, gd.keyField, nextUniqueKeyValue(gd.keyField, oldKey));
  }
  return row;
}

function createRowFromSourceRow(sourceRow) {
  const row = cloneData(sourceRow);
  removeCreateExcludedFields(row);
  return assignNewRowKeys(row, sourceRow);
}

function detailEditableControls() {
  // v0.7-objectarray-save-integrity:
  // 詳細ダイアログ内の編集可能コントロールを広く回収する。
  // chat/detailFooter は detailForm の外側(childArea)へ描画されるため、
  // detailFormだけを見ると追加コメント欄の編集・削除が保存されない。
  const root = $('detailDialog') ?? document;
  return [...root.querySelectorAll('input[data-field], select[data-field], textarea[data-field], [contenteditable][data-field]')];
}

function getControlValue(el) {
  if (el.hasAttribute('contenteditable')) return el.innerText ?? '';
  if (el instanceof HTMLSelectElement && el.multiple) {
    return [...el.selectedOptions].map(option => option.value).filter(value => value !== '');
  }
  return el.value;
}

function setControlValue(el, value) {
  const text = value == null ? '' : String(value);
  if (el.hasAttribute('contenteditable')) {
    el.innerText = text;
  } else {
    el.value = text;
  }
}

function isControlReadonly(el) {
  if (el.disabled) return true;
  if (el.hasAttribute('contenteditable')) return el.getAttribute('contenteditable') === 'false';
  return false;
}

function pasteCopiedRowToForm() {
  if (!copiedRow) {
    setStatus('コピー済み行がありません');
    return;
  }
  const gd = gridDef();
  detailEditableControls().forEach(inp => {
    const field = gd.fields.find(f => f.field === inp.dataset.field);
    if (!field || field.edit?.readonly || field.readonly || isControlReadonly(inp)) return;
    const value = getByPath(copiedRow, field.field);
    setControlValue(inp, value);
  });
  setStatus('コピー行の値を詳細ダイアログへ貼り付けました');
}

function addRowFromCopiedRow() {
  if (!copiedRow) {
    setStatus('コピー済み行がありません');
    return;
  }
  applyHeaderEdits();
  const row = createRowFromSourceRow(copiedRow);
  openNewDetail(row, 'コピー行から新規登録画面を開きました（反映するまで行は追加されません）');
}
function hideRowContextMenu() {
  const menu = $('rowContextMenu');
  if (menu) menu.classList.add('hidden');
}

function duplicateRowToNew(index) {
  if (!Array.isArray(currentRows) || index < 0 || !currentRows[index]) {
    setStatus('コピー新規する行を選択してください');
    return;
  }
  applyHeaderEdits();
  copiedRow = cloneData(currentRows[index]);
  const row = createRowFromSourceRow(copiedRow);
  const keyMsg = gridDef()?.keyField ? ` / ${gridDef().keyField}: ${getByPath(row, gridDef().keyField)}` : '';
  openNewDetail(row, `この行をコピーして新規登録画面へ遷移しました${keyMsg}（反映するまで行は追加されません）`);
}

function showRowContextMenu(x, y, index) {
  let menu = $('rowContextMenu');
  if (!menu) return;
  menu.innerHTML = '';

  const duplicateBtn = document.createElement('button');
  duplicateBtn.textContent = 'この行をコピーしてから新規登録画面へ遷移します。';
  duplicateBtn.addEventListener('click', () => { duplicateRowToNew(index); hideRowContextMenu(); });
  menu.appendChild(duplicateBtn);

  menu.style.left = x + 'px';
  menu.style.top = y + 'px';
  menu.classList.remove('hidden');
}
document.addEventListener('click', hideRowContextMenu);
document.addEventListener('keydown', (e) => {
  if (e.key === 'Escape') hideRowContextMenu();
  if (!$('detailDialog')?.open) return;
  if (e.key === 'F7') { e.preventDefault(); moveDetail(-1); }
  if (e.key === 'F8') { e.preventDefault(); moveDetail(1); }
  if (e.key === 'F12') { e.preventDefault(); applyDetail(e); }
});

function currentFilteredPosition() {
  if (selectedIndex < 0) return -1;
  return filteredRows.findIndex(x => x.index === selectedIndex);
}

function updateDetailNavButtons() {
  const pos = currentFilteredPosition();
  const prevBtn = $('prevDetailBtn');
  const nextBtn = $('nextDetailBtn');
  if (detailMode === 'new') {
    if (prevBtn) prevBtn.disabled = true;
    if (nextBtn) nextBtn.disabled = true;
    return;
  }
  if (prevBtn) prevBtn.disabled = pos <= 0;
  if (nextBtn) nextBtn.disabled = pos < 0 || pos >= filteredRows.length - 1;
}

function applyDetailInputsToRow(row) {
  if (!row) return;
  const gd = gridDef();
  if (typeof applyTargetContextDetailPanelEdits === 'function') applyTargetContextDetailPanelEdits(row);
  const seenRadio = new Set();

  detailEditableControls().forEach(inp => {
    if (!inp.dataset.field) return;
    if (inp.type === 'radio' && !inp.checked) return;

    const field = gd.fields.find(f => f.field === inp.dataset.field);
    if (!field || field.edit?.readonly || field.readonly || isControlReadonly(inp)) return;

    // objectArray / stringArray は childArea のサブグリッド表示が正本。
    // 表示用の件数文字列やtableセルから配列を上書きしない。
    if (field.type === 'objectArray' || field.type === 'stringArray') return;

    if (inp.type === 'radio') {
      const radioKey = `${field.field}:${inp.name}`;
      if (seenRadio.has(radioKey)) return;
      seenRadio.add(radioKey);
    }

    setByPath(row, field.field, convertValue(field.type, getControlValue(inp)));
  });

  if (typeof applyDetailSubGridEdits === 'function') {
    applyDetailSubGridEdits(row, gd);
  }
}

function applyDetailInputsToSelectedRow() {
  if (selectedIndex < 0) return;
  // PasteJSON後は保持中のRound Trip Draftを、F12または既存の前後移動確定で実データへ反映する。
  if (typeof consumeStudioJsonRoundTripDraft === 'function') {
    const roundTripDraft = consumeStudioJsonRoundTripDraft();
    if (roundTripDraft) {
      currentRows[selectedIndex] = roundTripDraft;
      return;
    }
  }
  applyDetailInputsToRow(currentRows[selectedIndex]);
}
function moveDetail(delta) {
  if (detailMode === 'new') return;
  const pos = currentFilteredPosition();
  const nextPos = pos + delta;
  if (pos < 0 || nextPos < 0 || nextPos >= filteredRows.length) return;
  applyDetailInputsToSelectedRow();
  selectedIndex = filteredRows[nextPos].index;
  renderGrid();
  openDetail(selectedIndex, true);
}

// v0.5-registry / v0.16.5-grid-card-document-renderer: high-level renderer registrations.
registerRenderer('gridTable', renderCompactGrid, ['table', 'compact', 'tableGrid', 'compactGrid']);
registerRenderer('gridDocument', renderDocumentGrid, ['document', 'card', 'cards', 'documentGrid', 'cardGrid']);
registerRenderer('grid', renderGrid);
